import { motion } from 'framer-motion';

// Masked line-by-line reveal. Pass lines as array of strings.
export const RevealLines = ({ lines, className = '', delay = 0, as: Tag = 'span' }) => {
  return (
    <span className={className}>
      {lines.map((line, i) => (
        <span key={i} className="reveal-line-wrap">
          <motion.span
            style={{ display: 'block' }}
            initial={{ y: '110%' }}
            animate={{ y: '0%' }}
            transition={{ duration: 1, delay: delay + i * 0.12, ease: [0.16, 1, 0.3, 1] }}
          >
            {line}
          </motion.span>
        </span>
      ))}
    </span>
  );
};

// Gentler, earlier-triggering reveal — avoids the "blank gap then sudden
// pop-in" feeling by starting the animation as soon as an element is
// nearly on screen, with a small offset + soft blur instead of a big jump.
export const FadeUp = ({ children, delay = 0, className = '', y = 24 }) => (
  <motion.div
    className={className}
    initial={{ opacity: 0, y, filter: 'blur(6px)' }}
    whileInView={{ opacity: 1, y: 0, filter: 'blur(0px)' }}
    viewport={{ once: true, amount: 0.15, margin: '0px 0px -10% 0px' }}
    transition={{ duration: 0.7, delay, ease: [0.22, 1, 0.36, 1] }}
  >
    {children}
  </motion.div>
);

// Same idea, but for a group of siblings that should settle in together
// rather than each firing its own separate scroll-trigger.
export const FadeUpGroup = ({ children, className = '', stagger = 0.08 }) => (
  <motion.div
    className={className}
    initial="hidden"
    whileInView="show"
    viewport={{ once: true, amount: 0.15, margin: '0px 0px -10% 0px' }}
    variants={{
      hidden: {},
      show: { transition: { staggerChildren: stagger } },
    }}
  >
    {children}
  </motion.div>
);

export const FadeUpItem = ({ children, className = '', y = 24 }) => (
  <motion.div
    className={className}
    variants={{
      hidden: { opacity: 0, y, filter: 'blur(6px)' },
      show: { opacity: 1, y: 0, filter: 'blur(0px)', transition: { duration: 0.7, ease: [0.22, 1, 0.36, 1] } },
    }}
  >
    {children}
  </motion.div>
);
